import concurrent.futures,datetime,hashlib,html.parser,json,pathlib,urllib.request
R=pathlib.Path(__file__).parent
SOURCES={
 'flutter-platforms':'https://docs.flutter.dev/reference/supported-platforms',
 'flutter-android-source':'https://raw.githubusercontent.com/flutter/flutter/abaf9c523780a608bd46686fd5e53740a07077f8/packages/flutter_tools/lib/src/android/gradle_utils.dart',
 'flutter-ios-template':'https://raw.githubusercontent.com/flutter/flutter/abaf9c523780a608bd46686fd5e53740a07077f8/packages/flutter_tools/templates/app/ios.tmpl/Runner.xcodeproj/project.pbxproj.tmpl',
