}
class Text(html.parser.HTMLParser):
 def __init__(self):super().__init__();self.skip=0;self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag in ('script','style'):self.skip+=1
 def handle_endtag(self,tag):
  if tag in ('script','style'):self.skip=max(0,self.skip-1)
 def handle_data(self,data):
  if not self.skip and data.strip():self.parts.append(data.strip())
def fetch(item):
 name,url=item;record={'id':name,'url':url,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  with urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'YourOwn-static-review/1.0','Accept':'text/html,text/plain;q=0.9,*/*;q=0.1'}),timeout=30) as res:
   raw=res.read(4_000_001);assert len(raw)<=4_000_000,'Response size limit';record.update(status=res.status,final_url=res.url,content_type=res.headers.get('Content-Type'),bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())
  (R/(name+'.raw')).write_bytes(raw);text=raw.decode('utf-8')
  if 'html' in (record['content_type'] or ''):
   parser=Text();parser.feed(text);text='\n'.join(parser.parts)
  (R/(name+'.txt')).write_text(text,encoding='utf-8');record['text_sha256']=hashlib.sha256((R/(name+'.txt')).read_bytes()).hexdigest()
 except Exception as error:record['error']=repr(error)
 return record
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:records=list(pool.map(fetch,SOURCES.items()))
(R/'sources.json').write_text(json.dumps(records,indent=2)+'\n',encoding='utf-8')
for record in records:print(record['id'],record.get('status'),record.get('bytes'),record.get('error',''))

